from fractions import Fraction as F
from itertools import permutations
cands={'1':[F(1,6),F(1,3),F(1,2)],'2':[F(1,3),F(1,3),F(1,2)],'3':[F(1,6),F(1,3),F(1,4)],'4':[F(1,2),F(1,2),F(1,3)]}
def ok(a): return sum(a)==1 and any(x==(y+z)/2 for x,y,z in permutations(a))
good=[k for k,a in cands.items() if ok(a)]
assert good==['1']
opts={'A':'3','B':'1','C':'4','D':'2'}
assert opts['B']==good[0]
for k in 'ACD': assert opts[k]!=good[0]
